  out: "برای هر جفت ناسازگار: نوع، درجهٔ طرفین، واقعی یا بدوی بودن، قاعدهٔ به‌کاررفته، طرف مقدم، پشتوانهٔ تأویل یا تحلیل منافع و مضار، و احتمال‌های نهایی. ورودی st_conflict (ثبت عام)، st_grade و st_final.",
