    { dom: "دین", src: "جزوه s80 (قاعدهٔ اول)", in: "یک خبر واحد که ظاهرش با برهانی یقینی ناسازگار است.", walk: "الف (برهان) یقینی، ب (خبر واحد) ظنی ← قاعدهٔ اول: برهان عقلی یقینی بر نقل ظنی مقدم است.", out: "برهان مقدم؛ خبر یا کنار می‌رود یا اگر ظاهرش قابل تأویل است، تأویل می‌شود." },
    { dom: "علم", src: "ساخته سامانه (بر پایهٔ قاعدهٔ ۴ جزوه)", in: "گزارشی پژوهشی می‌گوید فلان نوشیدنی ممنوع در شریعت، فایده‌ای مادی دارد؛ نتیجه گرفته می‌شود که حکم دینی با علم ناسازگار است.", walk: "نوع: علم تجربی–دین. یافتهٔ علمی بخشی از منافع مادی را دیده است. قاعدهٔ چهارم: دیدگاه دین جامع است و منافع و مضار مادی و اخروی را با هم می‌سنجد؛ وجود منفعت مادی با ممنوعیتی که بر برآیند همهٔ منافع و مضار تکیه دارد ناسازگار نیست. (نمونهٔ قرآنی هم‌سو: بقره ۲۱۹ دربارهٔ خمر و میسر: «فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإِثْمُهُمَا أَكْبَرُ مِنْ نَفْعِهِمَا».)", out: "تعارض بدوی؛ حل‌شده با قاعدهٔ ۴." },
    { dom: "خبر و رسانه", src: "ساخته سامانه", in: "خبری می‌گوید «فلان آیه با کیهان‌شناسی جدید در تضاد است.»", walk: "گام ۲: آیا موضوع و معنا یکی است؟ دلالت آیه نص است یا ظاهر؟ گام ۳: یافتهٔ کیهان‌شناختی چه درجه‌ای دارد (s51)؟ بدون این دو تعیین، هیچ قاعده‌ای اجرا نمی‌شود.", out: "معلق تا تعیین درجهٔ طرفین؛ تحقیق لازم: دلالت آیه (st_r_sources) و درجهٔ یافته (st_tajrobe)." }
