  philo: "اختلاف در آرای فقهی و تفسیری ناشی از عوامل روش‌شناختی و تاریخی است و هرگز به معنای نبود حقیقت عینی یا درستی همهٔ دیدگاه‌ها نیست، همان‌گونه که اختلاف آرا در علوم تجربی واقعیت را نفی نمی‌کند (s85). جزوه پنج ریشهٔ بنیادین برمی‌شمارد: ۱) تفاوت در گسترهٔ منابع معرفتی (مانند باور یا عدم باور به حجیت احادیث اهل بیت به سبب عصمت)؛ ۲) اختلاف در ارزیابی سندی و قواعد حجیت اخبار آحاد؛ ۳) تفاوت در معانی لغوی و اصطلاحی واژگان (مانند «کعب» در آیهٔ وضو: برآمدگی روی پا، مفصل ساق و قدم، یا قوزک پا)؛ ۴) توجه یا غفلت از قرائن پیوستهٔ کلام و شأن نزول/صدور احادیث (حدیث «خلق‌الله آدم علی صورته» که تقطیعش توهم تجسیم ساخت، در حالی که قرینهٔ کلام معصوم دلالتش را بر حرمت دشنام به افراد آشکار کرد؛ یا تقیه در برخی تعابیر برای حفظ جان اصحاب)؛ ۵) تفاوت در ظرفیت و وسع ادراکی محققان و محدودیت‌های بیرونی نظیر نابودی کتب و اسناد در طول تاریخ. این ایستگاه همین فهرست را به کاربرگ تشخیصی تبدیل می‌کند: در برابر هر اختلاف، به جای نتیجه گرفتن «پس همه درست‌اند» یا «پس هیچ‌کدام درست نیست»، پرسیده می‌شود کدام عامل در کار است؛ این همان تمایز «تکثر روش‌مند» از «نسبی‌گرایی» است (s78).",
