    { sec: "s76", use: "تمایز: تعدد قرائت‌ها درون‌دینی است و پلورالیسم دینی از آن فراتر می‌رود." },
    { sec: "s56", use: "تناقض خودارجاعی نسبی‌گرایی (ایستگاه عام st_selfref) که نقد نخست s83 مصداق آن است." },
    { sec: "s73", use: "اثبات اصول (از جمله توحید و حقانیت اسلام) از راه برهان عقلی قطعی؛ پشتوانهٔ نقد سوم s83." }
