window.EPI_CO.push(
  { id: "c_r_din", fa: "دین", en: "Religion", def: "مجموعهٔ اعتقادات اساسی و مقرراتی که روش زیستن برای نیل به سعادت حقیقی را معین می‌سازند؛ مرکب از دو بخش اعتقادات (قضایای خبری) و مقررات و احکام (گزاره‌های انشایی). پانوشت جزوه: «مجموع این اعتقاد و مقررات متناسب با آن که در مسیر زندگی مورد عمل قرار می‌گیرد، دین نامیده می‌شود.»", secs: ["s71"], vs: ["c_r_eteqadat", "c_r_ahkam"], crit: "آیا هم مجموعه‌ای از باورهای بنیادین دربارهٔ هستی و هم مقرراتی متناسب با آن برای شیوهٔ زیستن در کار است؟", conf: "دین را فقط مجموعهٔ باورها یا فقط مجموعهٔ مناسک دانستن.", ex: "توحید، نبوت و معاد (اعتقادات) در کنار احکام فردی، عبادی، اجتماعی و زیست‌محیطی (مقررات).", st: ["st_r_struct"] },
  { id: "c_r_eteqadat", fa: "اعتقادات (بخش خبری دین)", en: "Doctrines / beliefs", def: "بخش نخست دین که در قالب قضایای خبری از واقعیت‌های جهان حکایت دارد، مانند توحید، نبوت و معاد.", secs: ["s71"], vs: ["c_r_ahkam"], crit: "آیا جمله از «هست/نیست» خبر می‌دهد و می‌تواند با واقع منطبق یا نامنطبق باشد؟", conf: "خلط با احکام و انتظار «باید» از یک قضیهٔ خبری یا برعکس.", ex: "«خدا یگانه است»؛ «معاد هست».", st: ["st_r_struct"] },
  { id: "c_r_ahkam", fa: "مقررات و احکام (بخش انشایی دین)", en: "Precepts / rulings", def: "بخش دوم دین در قالب گزاره‌های انشایی و بایدها و نبایدها که روابط چهارگانهٔ انسان را در ساحت‌های فردی، عبادی، اجتماعی و زیست‌محیطی سامان می‌دهند.", secs: ["s71", "s38"], vs: ["c_r_eteqadat"], crit: "آیا جمله «باید/نباید» است؟ و به کدام ساحت از چهار ساحت تعلق دارد؟", conf: "صدق و کذب را مستقیماً بر انشاء حمل کردن؛ طبق s38 انشائیات متصف به صدق و کذب نمی‌شوند و آنچه سنجیده می‌شود ثبوت حکم در دین است.", ex: "حکمی عبادی (نماز)، حکمی اجتماعی (معاملات).", st: ["st_r_struct"] },
  { id: "c_r_haq_batil", fa: "دین حق و دین باطل", en: "True vs false religion", def: "تقسیم ادیان بر حسب انطباق یا عدم انطباق آموزه‌هایشان با واقع.", secs: ["s71", "s81"], vs: ["c_r_pl_epi"], crit: "معیار، انطباق با واقع است، نه شمار پیروان یا قدمت یا سودمندی اجتماعی.", conf: "حق بودن را به معنای مدارا نکردن با پیروان دیگر ادیان گرفتن (مغالطهٔ تلازم).", ex: "انحصار حقانیت برهانی در یک حقیقت (نمودار s81).", st: ["st_r_struct", "st_r_plural"] },
  { id: "c_r_epidin", fa: "معرفت‌شناسی دین", en: "Epistemology of religion", def: "شاخه‌ای از معرفت‌شناسی خاص که اعتبار و ارزش واقع‌نمایی آموزه‌های دینی (اعتقادی و عملی) را ارزیابی می‌کند و سهم هر راه شناخت (عقل برهانی، شهود، حس، نقل، رجوع به متخصص) را در ساختار دین معین می‌سازد؛ نتایجش متوقف بر حل مسائل معرفت‌شناسی عام است.", secs: ["s71", "s8"], vs: [], crit: "آیا پرسش دربارهٔ اعتبار و راه شناخت گزاره‌های دینی است (نه دربارهٔ محتوای کلامی آن‌ها)؟", conf: "خلط با کلام یا فقه: معرفت‌شناسی دین خود گزاره‌ها را اثبات نمی‌کند، اعتبار راه‌های اثباتشان را می‌سنجد.", ex: "پرسش «آیا معاد با تجربه اثبات‌پذیر است؟» پرسشی معرفت‌شناختی است.", st: ["st_r_struct"] },
  { id: "c_r_osul", fa: "اصول دین (اصول اعتقادی)", en: "Fundamental doctrines", def: "باورهای بنیادین دین که جزوه نمونه‌هایشان را اثبات خدا، صفات الهی، لزوم نبوت، معاد و حقانیت دین اسلام می‌آورد و تنها از طریق برهان‌های عقلی قطعی (مبتنی بر مقدمات بدیهی) اثبات می‌شوند.", secs: ["s73", "s74"], vs: ["c_r_furu"], crit: "آیا گزاره از پایه‌هایی است که اعتبار سایر بخش‌ها (از جمله اعتبار نقل) بر آن تکیه دارد؟", conf: "اثبات اصل با نقل یا تقلید؛ یا مطالبهٔ اثبات تجربی برای آن.", ex: "اثبات خدا، لزوم نبوت، معاد.", st: ["st_r_struct", "st_r_sources", "st_resp"] },
  { id: "c_r_furu", fa: "فروع دین (احکام فرعی و جزئیات شریعت)", en: "Derivative rulings", def: "جزئیات تکالیف و معارف فرعی که از راه نقل‌های معتبر تثبیت می‌شوند و غیرمتخصص در آن‌ها به حکم عقل از کارشناس اعلم تقلید می‌کند.", secs: ["s73", "s74"], vs: ["c_r_osul"], crit: "آیا موضوع یک تکلیف عملی یا جزئیات شریعت/تاریخ معصومان است؟", conf: "سنجش فروع با معیار برهان عقلی محض، یا تقلید در اصول به قیاس فروع.", ex: "حکم یک معامله؛ کیفیت یک عبادت.", st: ["st_r_struct", "st_r_sources"] },
  { id: "c_r_daraje", fa: "درجات اعتبار معرفت دینی", en: "Degrees of epistemic validity", def: "یکنواخت نبودن اعتبار معارف دینی: معارف مبتنی بر علم حضوری، اصول بدیهی یا برهان عقلی یقینی اعتبار صددرصدی و خطاناپذیر دارند؛ معارف متکی بر شواهد ظنی معتبر در رتبه‌های بعدی سنجیده می‌شوند.", secs: ["s72", "s80"], vs: [], crit: "پشتوانهٔ گزاره چیست: حضوری/بدیهی/برهان یقینی، یا شاهد ظنی معتبر؟", conf: "همهٔ معارف دینی را هم‌وزن دیدن.", ex: "توحید برهانی (یقینی) در برابر حکمی فرعی از خبر واحد موثق (ظنی معتبر).", st: ["st_r_struct", "st_r_conflict"] },
  { id: "c_r_shuhud_fitri", fa: "شهود فطری به خدا", en: "Innate presential awareness of God", def: "شهود (علم حضوری) نسبت به خداوند که در مرتبه‌ای ضعیف در فطرت همگان نهاده شده است.", secs: ["s72", "s25"], vs: ["c_r_mokashefe"], crit: "یافتی حضوری و همگانی (درک فقر و وابستگی وجودی) که هنوز به مفاهیم و استدلال تفصیلی درنیامده است.", conf: "پنداشتن این‌که این شهود ضعیف، شناخت تفصیلی ذات و صفات را می‌دهد؛ طبق s25 علم حضوری انسان به خدا احاطی نیست و شناخت تفصیلی بر عقل و وحی تکیه دارد.", ex: "درک فقر وجودی به علت که حتی منکران نیز دارند (s25).", st: ["st_r_struct", "st_r_sources"] },
  { id: "c_r_mokashefe", fa: "مکاشفه، الهام و وحی (مراتب عالی شهود)", en: "Unveiling, inspiration, revelation", def: "مراتب عالی شهود که شهود فطری در اولیای الهی به آن‌ها ارتقا می‌یابد. اصل شهود حضوری مصون از خطاست ولی تفاسیر حصولی بعدی انسان غیرمعصوم ممکن است خطا کند؛ وحی و الهام نبوی با برهان عصمت ایمن از خطاست.", secs: ["s72", "s23"], vs: ["c_r_shuhud_fitri", "c_r_esmat"], crit: "آیا دارندهٔ آن معصوم است؟ اگر نه، اصل یافت را از تفسیر جدا کن و تفسیر را با عقل و وحی بسنج.", conf: "خطاناپذیر دانستن تفسیر مکاشفهٔ غیرمعصوم به اعتبار «شهود بودن».", ex: "ماجرای حسن بصری (s23): ندایی را شنید ولی در تطبیق و استنباط معنایش لغزید.", st: ["st_r_struct", "st_r_sources"] },
  { id: "c_r_esmat", fa: "عصمت و برهان عصمت", en: "Infallibility (ʿiṣma)", def: "ایمنی معصوم از خطا که با برهان اثبات می‌شود؛ پس از اثبات آن، سخن معصوم اعتبار قطعی دارد و وحی و الهام نبوی ایمن از خطا شمرده می‌شود. باور یا عدم باور به آن در اهل بیت از عوامل اختلاف در گسترهٔ منابع است.", secs: ["s72", "s74", "s85"], vs: ["c_r_qawl_masum"], crit: "آیا اعتبار قطعی یک سخن به عصمت گوینده تکیه دارد؟ و آیا عصمت او پیش‌تر اثبات شده است؟", conf: "عصمت گوینده را جایگزین اثبات صدور سخن از او کردن.", ex: "اعتبار قطعی سخن معصوم «پس از اثبات عصمت» (s74).", st: ["st_r_struct", "st_r_sources", "st_r_disagree"] },
  { id: "c_r_qawl_masum", fa: "استناد به قول معصوم", en: "Reliance on the infallible's word", def: "یکی از دو وجه استناد به معرفت دیگران در دین که پس از اثبات عصمت اعتباری قطعی دارد.", secs: ["s74"], vs: ["c_r_taqlid"], crit: "دو پرسش جدا: آیا صدور سخن از معصوم ثابت است (سند و دلالت)؟ آیا عصمت او اثبات شده است؟", conf: "قطعی دانستن هر سخن منسوب، بدون بررسی صدور.", ex: "روایتی ثابت‌الصدور از معصوم.", st: ["st_r_sources"] },
  { id: "c_r_taqlid", fa: "تقلید از اعلم (رجوع به کارشناس دینی)", en: "Following the most learned jurist", def: "رجوع غیرمتخصص به متخصصان و کارشناسان دینی مانند مفسران و فقها که به حکم عقل، تقلید از اعلم را در فروع دینی ایجاب می‌کند؛ مصداق دینی استناد به تخصص دیگران (s49).", secs: ["s74", "s49", "s1"], vs: ["c_r_qawl_masum", "c_r_osul"], crit: "آیا موضوع فرع (تکلیف عملی) است، مرجع کارشناس دینی است و اعلمیتش احراز شده است؟", conf: "تقلید در اصول اعتقادی؛ یا رجوع به غیرکارشناس به نام تقلید.", ex: "عمل به فتوای مرجع اعلم در حکم یک معامله.", st: ["st_r_sources", "st_resp"] },
  { id: "c_r_alam", fa: "اعلم", en: "The most knowledgeable", def: "داناترین کارشناس دینی در فروع که عقل تقلید از او را لازم می‌داند.", secs: ["s74"], vs: ["c_r_taqlid"], crit: "مقایسهٔ تبحر کارشناسان در همان روش (دو رکن s49: اعتبار روش و درجهٔ تبحر و پایبندی).", conf: "شهرت یا مقام را با اعلمیت یکی گرفتن.", ex: "از میان چند فقیه، کسی که در استنباط داناتر است.", st: ["st_r_sources"] },
  { id: "c_r_hiss_dini", fa: "نقش مقدماتی حس در دین", en: "Preparatory role of sense", def: "مفاهیم بنیادین دینی مانند توحید و معاد محسوس نیستند، اما حس مجرای دریافت معجزات، تلاوت آیات قرآن و شنیدن روایات است.", secs: ["s72"], vs: ["c_r_tajrobe_dini"], crit: "آیا حس در این‌جا خودِ مدعا را اثبات می‌کند یا فقط مجرای رسیدن داده (متن، معجزه) است؟", conf: "یا حس را بی‌نقش دانستن، یا از آن اثبات مستقیم توحید و معاد را انتظار داشتن.", ex: "شنیدن یک روایت از راوی؛ دیدن معجزه.", st: ["st_r_struct", "st_r_sources"] },
  { id: "c_r_tajrobe_dini", fa: "بی‌راهی تجربهٔ حسی در اثبات دین", en: "Empirical method's lack of direct access", def: "تجربهٔ حسی به صورت مستقیم هیچ راهی به اثبات اصول اعتقادی یا اعتبارسنجی احکام و مقررات تشریعی ندارد.", secs: ["s74", "s51"], vs: ["c_r_hiss_dini"], crit: "آیا مدعا (اصل اعتقادی یا اعتبار حکم) از راه وضع و رفع شروط تجربی قابل آزمون است؟ طبق جزوه نه.", conf: "خلط «تجربه» در اصطلاح جزوه (روش عقلی-مشاهده‌ای) با «تجربهٔ دینی» در ادبیات غربی که به شهود نزدیک‌تر است (توضیح سامانه).", ex: "مطالبهٔ آزمایش برای اثبات معاد.", st: ["st_r_struct"] },
  { id: "c_r_yad_dini", fa: "یادآوری در منظومهٔ دین", en: "Memory in religious knowledge", def: "قوه‌ای که ابزار استمرار و تطبیق آموخته‌های دینی بر رفتار عملی در طول زمان است؛ اعتبارش تابع وثاقت حافظه و اعتبار معرفت نخستین است (s52).", secs: ["s74", "s52"], vs: [], crit: "آموختهٔ نخستین از کجا و با چه اعتباری بوده و آیا حافظه با منبع تطبیق داده شده است؟", conf: "اعتبار یادآوری را بیش از اعتبار آموختهٔ نخستین پنداشتن.", ex: "به یاد آوردن حکمی که سال‌ها پیش آموخته شده.", st: ["st_r_sources"] },
  { id: "c_r_arzesh_aqli", fa: "ارزش‌های عام عقلانی", en: "Universal rational values", def: "یکی از اجزای منظومهٔ دین در کنار باورهای عقلی یقینی، ضروریات قطعی فقهی و احکام فرعی نقلی؛ مثال جزوه: حسن عدل و قبح ظلم.", secs: ["s74"], vs: ["c_r_zaruri"], crit: "آیا عقل بدون نیاز به نقل آن را درمی‌یابد؟", conf: "آن را صرفاً حکمی نقلی دانستن.", ex: "حسن عدل و قبح ظلم.", st: ["st_r_struct"] },
  { id: "c_r_zaruri", fa: "ضروریات قطعی فقهی", en: "Juristic necessities", def: "احکامی که در منظومهٔ دین قطعی‌اند و جزوه آن‌ها را جزئی جدا از احکام فرعی معتبر نقلی می‌شمارد.", secs: ["s74"], vs: ["c_r_furu", "c_r_arzesh_aqli"], crit: "آیا ثبوت حکم در دین قطعی است و نه محل اجتهاد ظنی؟", conf: "هم‌رتبه کردن آن با احکام فرعی ظنی.", ex: "— (جزوه مثال مشخص نیاورده است)", st: ["st_r_struct"] },
  { id: "c_r_sanad", fa: "سند", en: "Chain of transmission (isnād)", def: "وضعیت ناقلان خبر؛ از این حیث خبر متواتر یا واحد است.", secs: ["s73", "s47", "s48"], vs: ["c_r_dalalat", "c_r_qarine"], crit: "پرسش «چه کسانی و چند نفر این را نقل کرده‌اند و ثقه‌اند؟»", conf: "خلط سند با دلالت: سند قطعی، دلالت را قطعی نمی‌کند.", ex: "حدیث غدیر از حیث سند.", st: ["st_r_sources", "st_r_disagree"] },
  { id: "c_r_motavater", fa: "خبر متواتر", en: "Mass-transmitted report (mutawātir)", def: "خبری که شمار ناقلانش چنان است که تبانی آنان بر کذب عقلاً محال است و یقین قطعی می‌آورد. پانوشت جزوه (ویکی‌شیعه): حدیث غدیر که تنها در طبقهٔ صحابه بیش از ۱۰۰ نفر و حدیث ثقلین که در طبقهٔ صحابه بیش از ۸۰ نفر روایت کرده‌اند.", secs: ["s73", "s48"], vs: ["c_r_vahed"], crit: "آیا در هر طبقهٔ نقل شمار ناقلان مستقل به حدی است که تبانی بر کذب محال باشد؟", conf: "متواتر بودن سند را به معنای قطعی بودن دلالت گرفتن.", ex: "حدیث غدیر؛ حدیث ثقلین.", st: ["st_r_sources", "st_r_conflict"] },
  { id: "c_r_vahed", fa: "خبر واحد (اخبار آحاد)", en: "Solitary report (khabar al-wāḥid)", def: "خبری که به حد تواتر نمی‌رسد و به موثق و غیرموثق تقسیم می‌شود؛ بررسی آن کار علم رجال و قواعد درایه است و قواعد حجیت آن از عوامل اختلاف فقیهان است.", secs: ["s73", "s48", "s85"], vs: ["c_r_motavater"], crit: "شمار ناقلان کمتر از حد تواتر است؟ پس وثاقت تک‌تک راویان باید بررسی شود.", conf: "رد کامل همهٔ اخبار آحاد یا پذیرش بی‌بررسی آن‌ها.", ex: "روایتی با یک زنجیرهٔ راویان.", st: ["st_r_sources", "st_r_disagree", "st_r_conflict"] },
  { id: "c_r_rejal", fa: "علم رجال", en: "ʿIlm al-rijāl", def: "طبق جزوه، در اخبار غیرمتواتر علم رجال و قواعد درایه به بررسی راویان و دلالت الفاظ می‌پردازند. (توضیح سامانه: علم رجال به‌طور خاص شناخت احوال راویان حدیث از حیث وثاقت و ضعف است.)", secs: ["s73"], vs: ["c_r_deraye"], crit: "پرسش دربارهٔ «راوی» است: ثقه است یا نه؟", conf: "رجال را بررسی متن و معنای حدیث پنداشتن.", ex: "بررسی وثاقت یکایک راویان یک خبر واحد.", st: ["st_r_sources", "st_r_disagree"] },
  { id: "c_r_deraye", fa: "علم درایه (درایة‌الحدیث)", en: "ʿIlm al-dirāya", def: "طبق جزوه، قواعد درایة‌الحدیث همراه با رجال در اخبار غیرمتواتر به بررسی راویان و دلالت الفاظ می‌پردازند. (توضیح سامانه: درایه دانش اقسام حدیث و اصطلاحات سند و متن، مانند صحیح، موثق، ضعیف، است.)", secs: ["s73"], vs: ["c_r_rejal"], crit: "پرسش دربارهٔ قواعد کلی طبقه‌بندی و سنجش خبر است، نه وضع یک راوی خاص.", conf: "یکی گرفتن درایه با رجال.", ex: "تعیین این‌که خبری با فلان ویژگی سندی «موثق» است.", st: ["st_r_sources"] },
  { id: "c_r_dalalat", fa: "دلالت", en: "Signification", def: "نسبت الفاظ متن با مقصود؛ از این حیث متن یا صریح (نص) است یا احتمال تفاسیر متعدد دارد.", secs: ["s73", "s48"], vs: ["c_r_sanad"], crit: "پرسش «این لفظ دقیقاً بر چه دلالت دارد و آیا احتمال دیگری دارد؟»", conf: "قطعی بودن سند را دلیل قطعی بودن معنا گرفتن.", ex: "دلالت «کعبین» در آیهٔ وضو.", st: ["st_r_sources", "st_r_conflict", "st_r_disagree"] },
  { id: "c_r_nass", fa: "نص", en: "Explicit text (naṣṣ)", def: "کلامی که الفاظش بر معنایی صریح دلالت می‌کنند و احتمال خلاف نمی‌دهند.", secs: ["s48", "s73", "s80"], vs: ["c_r_zaher"], crit: "آیا هیچ معنای دیگری برای عبارت در زبان محاوره محتمل نیست؟", conf: "هر ظاهر قوی را نص پنداشتن.", ex: "نقل «قطعی‌الدلاله» در قاعدهٔ اول حل تعارض.", st: ["st_r_sources", "st_r_conflict"] },
  { id: "c_r_zaher", fa: "ظاهر / غیرنص", en: "Apparent meaning (ẓāhir)", def: "کلامی که احتمالات دیگر را می‌پذیرد و نیازمند قرینه است؛ «ظواهر متون» در قاعدهٔ سوم حل تعارض، در صورت ناسازگاری با اصل عقلی قطعی، به معنای کنایی بازگردانده می‌شوند.", secs: ["s48", "s73", "s80"], vs: ["c_r_nass", "c_r_tawil"], crit: "آیا معنای نخستین عبارت، تنها معنای محتمل آن نیست؟", conf: "ظاهر را قطعی گرفتن و آن را بر برهان عقلی یقینی مقدم داشتن.", ex: "ظاهر «یدالله».", st: ["st_r_sources", "st_r_conflict"] },
  { id: "c_r_qarine", fa: "قرینه (شواهد و قرائن)", en: "Contextual evidence", def: "شواهد تأییدکننده یا تعیین‌کنندهٔ جانبی که سومین محور سنجش خبر است؛ در دین شامل هماهنگی با قرآن، قرائن پیوستهٔ کلام، شأن صدور و احتمال تقیه.", secs: ["s73", "s48", "s80", "s85"], vs: ["c_r_sanad", "c_r_dalalat"], crit: "آیا چیزی بیرون از خود لفظ، معنای آن یا اعتبار آن را تأیید یا تعیین می‌کند؟", conf: "اکتفا به لفظ تقطیع‌شده و نادیده گرفتن ادامهٔ کلام.", ex: "قرینهٔ کلام معصوم در حدیث «خلق‌الله آدم علی صورته».", st: ["st_r_sources", "st_r_disagree"] },
  { id: "c_r_mowafeq_quran", fa: "هماهنگی با قرآن (مرجح روایت)", en: "Agreement with the Qurʾan", def: "از مرجحات قاعدهٔ دوم حل تعارض: در تعارض ادلهٔ ظنی، روایات موثق‌تر و موافق با قرآن رجحان دارند.", secs: ["s80"], vs: [], crit: "آیا مضمون روایت با قرآن سازگار است؟", conf: "به کار بردن این مرجح در تعارض یک یقینی با یک ظنی (که جایش قاعدهٔ اول است).", ex: "ترجیح روایت هماهنگ با قرآن بر روایت ناهماهنگ.", st: ["st_r_conflict", "st_r_sources"] },
  { id: "c_r_taqaddom", fa: "تقدم یقینی بر ظنی", en: "Priority of certain over probable", def: "قاعدهٔ اول و محوری حل تعارض: برهان عقلی یقینی بر نقل ظنی، و نقل قطعی‌السند و الدلاله بر استدلال ظنی مقدم است.", secs: ["s80", "s53"], vs: ["c_r_tarjih"], crit: "آیا یک طرف تعارض یقینی و دیگری ظنی است؟", conf: "پنداشتن این‌که عقل همیشه بر نقل مقدم است، حتی وقتی استدلال عقلی ظنی و نقل قطعی است.", ex: "تقدم برهان نفی تجسم بر ظاهر ظنی.", st: ["st_r_conflict"] },
  { id: "c_r_tarjih", fa: "ترجیح احتمال صدق بالاتر", en: "Preference for higher probability", def: "قاعدهٔ دوم حل تعارض: در تعارض ادلهٔ ظنی، معرفت دارای اعتبار و احتمال صدق بالاتر ترجیح می‌یابد، مانند روایات موثق‌تر و هماهنگ با قرآن.", secs: ["s80", "s53"], vs: ["c_r_taqaddom"], crit: "آیا هر دو طرف ظنی‌اند؟", conf: "ترجیح بر پایهٔ شهرت یا خوشایندی به جای احتمال صدق.", ex: "ترجیح روایت موثق هماهنگ با قرآن بر روایت ضعیف.", st: ["st_r_conflict"] },
  { id: "c_r_tawil", fa: "تأویل ظواهر (بازگرداندن به معنای کنایی)", en: "Figurative interpretation (taʾwīl)", def: "قاعدهٔ سوم حل تعارض: بازگرداندن ظواهر متون نقلی که با اصول عقلی قطعی ناسازگارند به معانی نمادین کنایی؛ مانند «یدالله» با تکیه بر براهین عقلی نفی تجسم. (نکتهٔ متنی: در متن s80 این مثال ذیل «مرتبهٔ بعد: ترجیح معرفت دارای اعتبار و احتمال صدق بالاتر» آمده و نمودار همان بخش آن را قاعدهٔ سوم جداگانه شمرده است.)", secs: ["s80"], vs: ["c_r_namadin", "c_r_zaher"], crit: "آیا برهان عقلی قطعی مشخصی ظاهر را ناممکن می‌کند و تأویل فقط به همان عبارت محدود است؟", conf: "یکی گرفتن آن با نمادین‌انگاری کل زبان دین که s77 رد می‌کند.", ex: "یدالله.", st: ["st_r_conflict", "st_r_readings"] },
  { id: "c_r_tajsim", fa: "تجسیم (تجسم) و نفی آن", en: "Anthropomorphism (tajsīm)", def: "نسبت دادن جسم و اعضای جسمانی به خدا؛ براهین عقلی نفی تجسم مبنای تأویل ظواهری چون یدالله است، و تقطیع حدیث «خلق‌الله آدم علی صورته» سبب توهم تجسیم شد.", secs: ["s80", "s85"], vs: ["c_r_tawil"], crit: "آیا برداشت، صفات جسمانی را به خدا نسبت می‌دهد؟", conf: "تکیه بر ظاهر یا تکهٔ تقطیع‌شده و غفلت از برهان و قرینه.", ex: "توهم تجسیم از «خلق‌الله آدم علی صورته».", st: ["st_r_conflict", "st_r_disagree"] },
  { id: "c_r_taarod_badvi", fa: "تعارض بدوی (ظاهری)", en: "Prima facie conflict", def: "ناسازگاری‌ای که در نگاه نخست می‌نماید و با دقت رفع می‌شود؛ جزوه دربارهٔ تعارض‌های بدوی علم و دین می‌گوید توجه به دیدگاه جامع دین نسبت به منافع و مضار اخروی و مادی آن را برطرف می‌کند.", secs: ["s80"], vs: [], crit: "آیا با روشن کردن موضوع، جهت یا دامنهٔ هر گزاره، ناسازگاری از میان می‌رود؟", conf: "هر ناسازگاری ظاهری را تعارض واقعی پنداشتن.", ex: "یافتهٔ علمی دربارهٔ منفعت مادی یک امر در برابر حکم دینی که برآیند منافع و مضار مادی و اخروی را می‌سنجد.", st: ["st_r_conflict"] },
  { id: "c_r_jame", fa: "دیدگاه جامع دین (منافع و مضار مادی و اخروی)", en: "Religion's comprehensive view", def: "قاعدهٔ چهارم حل تعارض: دین در احکام خود گسترهٔ جامع منافع و مضار مادی و اخروی را لحاظ می‌کند؛ توجه به این، تعارض ظاهری علم و دین را برطرف می‌کند.", secs: ["s80"], vs: ["c_r_taarod_badvi"], crit: "آیا یافتهٔ علمی فقط بخشی از منافع یا مضار را سنجیده است؟", conf: "سنجیدن حکم دینی فقط با معیار سود مادی.", ex: "— (مثال در ایستگاه st_r_conflict ساختهٔ سامانه است)", st: ["st_r_conflict"] },
  { id: "c_r_mas_resp", fa: "تکلیف‌آوری شناخت (جهل با امکان تحقیق عذر نیست)", en: "Epistemic responsibility", def: "شناخت موجه احکام و گزاره‌های دینی تکلیف‌آور است و در صورت وجود راه تحقیق، جهل عذر به شمار نمی‌رود.", secs: ["s80"], vs: ["c_r_qasir", "c_r_moqassir"], crit: "آیا راه تحقیقی در دسترس بود؟", conf: "صرف ندانستن را عذر دانستن.", ex: "کسی که می‌توانست حکم را بپرسد و نپرسید.", st: ["st_resp"] },
  { id: "c_r_qasir", fa: "جاهل قاصر", en: "Inculpably ignorant", def: "کسی که امکان دستیابی به حقیقت را نداشته است؛ رستگاری او را نیز در بر می‌گیرد (s86). جزوه قاصران را «ناآگاهان غیرمعاند» می‌خواند (s83).", secs: ["s86", "s83"], vs: ["c_r_moqassir", "c_r_moaned"], crit: "آیا راه دستیابی به حقیقت برای او وجود نداشته است؟", conf: "هر ناآگاهی را قصور دانستن، حتی وقتی راه تحقیق بوده است.", ex: "کسی که پیام دین حق هرگز به او نرسیده و راهی به آن نداشته است.", st: ["st_resp", "st_r_plural"] },
  { id: "c_r_moqassir", fa: "مقصر", en: "Culpably ignorant", def: "جزوه واژه را بی‌تعریف و در کنار «معاندان» آورده است: محرومیت از رحمت تنها دامنگیر معاندان و مقصران است (s86). (تعریف مقابله‌ای سامانه، از روی تعریف جزوه برای قاصر و اصل s80: کسی که راه دستیابی به حقیقت را داشته ولی آن را نپیموده است.)", secs: ["s86", "s80"], vs: ["c_r_qasir", "c_r_moaned"], crit: "آیا راه تحقیق بوده و استفاده نشده است؟", conf: "مقصر را با معاند یکی گرفتن؛ مقصر لزوماً دشمنی آگاهانه با حق ندارد.", ex: "کسی که می‌توانست تحقیق کند و از سر سهل‌انگاری نکرد.", st: ["st_resp", "st_r_plural"] },
  { id: "c_r_moaned", fa: "معاند", en: "Obstinate denier", def: "در جزوه کنار مقصر به‌عنوان کسی که از رحمت محروم است آمده و قاصران «ناآگاهان غیرمعاند» نامیده شده‌اند. (توضیح سامانه: معاند کسی است که با وجود آگاهی با حق دشمنی می‌کند.)", secs: ["s83", "s86"], vs: ["c_r_qasir", "c_r_moqassir"], crit: "آیا حق را شناخته و با آن ستیزه می‌کند؟", conf: "هر مخالف یا ناآگاهی را معاند خواندن.", ex: "— (جزوه مصداق مشخص نیاورده است)", st: ["st_r_plural", "st_resp"] },
  { id: "c_r_taddod", fa: "نظریهٔ تعدد قرائت‌ها", en: "Theory of multiple readings", def: "نظریه‌ای که مدعی است همهٔ فهم‌ها و برداشت‌های متفاوت و متعارض از متن دینی اعتبار یکسان دارند؛ صرفاً گزارش وقوع تاریخی اختلافات تفسیری نیست، بلکه مشروعیت معرفتی یکسان برای همهٔ خوانش‌ها قائل است؛ یکی از مبانی اصلی‌اش هرمنوتیک فلسفی است.", secs: ["s76", "s77", "s78"], vs: ["c_r_takassor_ravesh"], crit: "آیا ادعا هنجاری («همه به یک اندازه معتبرند») است یا فقط توصیفی («اختلاف رخ داده»)؟", conf: "یکی گرفتن آن با پذیرش وقوع اختلاف تفسیری یا با تکثر روش‌مند فتاوا.", ex: "«هر کس برداشت خودش را از قرآن دارد و هیچ‌کدام بر دیگری برتری ندارد.»", st: ["st_r_readings"] },
  { id: "c_r_namadin", fa: "نمادین‌انگاری و اسطوره‌ای‌انگاری زبان دین", en: "Symbolic/mythic view of religious language", def: "ادعای این‌که زبان دین نمادین و اسطوره‌ای است و از واقع‌نمایی جداست؛ جزوه آن را مردود می‌داند زیرا هدف گزاره‌های دینی پاسخ واقعی به مسائل آغاز و انجام هستی است و این تفکیک کارآمدی هدایتی و احکام عملی را ساقط می‌کند. هیک نیز زبان دین را نمادین اعلام کرد.", secs: ["s77", "s82", "s83"], vs: ["c_r_tawil"], crit: "آیا ادعا فراگیر است (کل زبان دین) و بدون برهان قطعی موردی؟", conf: "یکی گرفتن آن با تأویل موردی و برهان‌مند (قاعدهٔ سوم s80).", ex: "«داستان‌های دینی اسطوره‌اند و پیامشان فقط اخلاقی است.»", st: ["st_r_readings", "st_r_plural"] },
  { id: "c_r_laghv", fa: "لغو هدایت و بعثت", en: "Futility of guidance", def: "پیامد نظریهٔ تعدد قرائت‌ها بر پایهٔ هرمنوتیک فلسفی: اگر راه شناخت پیام متن بسته باشد، بعثت انبیا، تشریع احکام و مفاهیمی چون اطاعت و عصیان کارکرد خود را از دست می‌دهند و محاوره بی‌معنا می‌شود.", secs: ["s77"], vs: [], crit: "آیا با فرض مدعا، اطاعت و عصیان نسبت به پیامی قابل‌شناخت معنا دارد؟", conf: "پنداشتن این‌که می‌توان پیام را دست‌نیافتنی دانست و همچنان از اطاعت سخن گفت.", ex: "آزمون پیامد در ایستگاه st_r_readings.", st: ["st_r_readings"] },
  { id: "c_r_batn", fa: "بطن (بطون قرآن)", en: "Inner layers of the Qurʾan", def: "لایه‌های باطنی قرآن که معانی طولی و منسجمی‌اند، در بطن کلام الهی تعبیه شده‌اند و کشفشان نیازمند مقدمات معین است؛ نه قرائت‌های عرضی و متناقض.", secs: ["s78"], vs: ["c_r_tuli_arzi"], crit: "آیا معنای ادعاشده با ظاهر و دیگر معانی سازگار و در طول آن است و از مقدمات معین به دست آمده؟", conf: "تمسک به وجود ظاهر و باطن برای اثبات تعدد قرائت‌ها (مغالطه).", ex: "— (جزوه مصداق مشخصی از یک بطن نیاورده است)", st: ["st_r_readings"] },
  { id: "c_r_tuli_arzi", fa: "معانی طولی در برابر قرائت‌های عرضی", en: "Vertical layers vs horizontal readings", def: "معانی طولی: لایه‌هایی منسجم و سازگار در طول یکدیگر؛ قرائت‌های عرضی: برداشت‌های هم‌سطح، متناقض و هم‌ارز که تعدد قرائت‌ها به یک اندازه مشروع می‌شمارد.", secs: ["s78"], vs: ["c_r_batn", "c_r_taddod"], crit: "آیا پذیرش یکی مستلزم نفی دیگری است؟ اگر آری، عرضی‌اند.", conf: "هر معنای متفاوت را «بطن» نامیدن.", ex: "نمودار تقابل فصل ۱۴.", st: ["st_r_readings"] },
  { id: "c_r_ijtihad", fa: "اجتهاد", en: "Juristic reasoning (ijtihād)", def: "کاربست روش‌مند موازین علمی برای دستیابی به حقیقت واحد در فهم احکام؛ اختلاف فتاوا حاصل آن است.", secs: ["s78", "s85"], vs: ["c_r_taddod"], crit: "آیا با موازین معتبر و برای کشف واقع انجام شده است؟", conf: "اختلاف حاصل از اجتهاد را نشانهٔ نسبیت حقیقت دانستن.", ex: "دو فقیه با دو استنباط از یک مسئله.", st: ["st_r_readings", "st_r_disagree"] },
  { id: "c_r_fatwa", fa: "فتوا و تکثر فتاوا", en: "Fatwa and plurality of fatwas", def: "نظر کارشناسی فقیه در حکم شرعی که اعتبارش بر مدار احتمال کشف واقع می‌چرخد؛ تکثر فتاوا ناشی از اجتهاد روش‌مند است، مانند اختلاف‌نظرهای تخصصی در پزشکی و مهندسی، و نشانهٔ نسبی‌گرایی نیست.", secs: ["s78", "s74"], vs: ["c_r_taddod"], crit: "آیا اختلاف به عوامل روش‌شناختی و تاریخی (s85) قابل تبیین است؟", conf: "از تفاوت فتاوا، برابری همهٔ برداشت‌ها را نتیجه گرفتن.", ex: "دو مرجع با دو فتوای متفاوت.", st: ["st_r_readings", "st_r_disagree", "st_r_sources"] },
  { id: "c_r_takassor_ravesh", fa: "تکثر روش‌مند (در برابر نسبی‌گرایی هرمنوتیکی)", en: "Methodical plurality", def: "تکثر فهم‌ها و فتواها که بر پایهٔ امکان کشف روش‌مند واقعیت شکل گرفته و با نسبی‌گرایی حاکم بر تعدد قرائت‌ها مغایرت بنیادی دارد.", secs: ["s78", "s85"], vs: ["c_r_taddod"], crit: "آیا هر طرف خود را در جست‌وجوی حقیقتی واحد و ملتزم به موازین می‌داند؟", conf: "هر تکثری را نسبی‌گرایی دانستن.", ex: "نمودار تقابل فصل ۱۴ و نقشهٔ مفهومی آن.", st: ["st_r_readings", "st_r_disagree"] },
  { id: "c_r_hojjiyya", fa: "حجیت", en: "Probative authority", def: "اعتبار یک منبع یا دلیل برای استناد؛ جزوه از «حجیت احادیث اهل بیت به سبب عصمت» و «قواعد حجیت اخبار آحاد» به‌عنوان دو محل اختلاف یاد می‌کند.", secs: ["s85"], vs: [], crit: "آیا این منبع اصلاً جزو ادلهٔ معتبر برای این طرف است؟", conf: "خلط پرسش حجیت (آیا منبع معتبر است؟) با پرسش دلالت (منبع چه می‌گوید؟).", ex: "اختلاف در حجیت احادیث اهل بیت.", st: ["st_r_disagree", "st_r_sources"] },
  { id: "c_r_taqti", fa: "تقطیع", en: "Truncation", def: "جدا کردن بخشی از متن از قرائن پیوستهٔ آن؛ مثال جزوه: تقطیع حدیث «خلق‌الله آدم علی صورته» که سبب توهم تجسیم شد.", secs: ["s85"], vs: ["c_r_qarine"], crit: "آیا صدر و ذیل و بافت کامل متن دیده شده است؟", conf: "اکتفا به جملهٔ مشهور یک روایت.", ex: "«خلق‌الله آدم علی صورته».", st: ["st_r_disagree", "st_r_sources"] },
  { id: "c_r_shan", fa: "شأن نزول / شأن صدور", en: "Occasion of revelation / issuance", def: "زمینه و موقعیتی که آیه یا حدیث در آن نازل یا صادر شده است؛ توجه یا غفلت از آن (همراه قرائن پیوستهٔ کلام) از عوامل اختلاف است. متن s85 «شأن نزول احادیث» و نمودار آن «شأن صدور» آورده است.", secs: ["s85"], vs: ["c_r_qarine", "c_r_taqiyya"], crit: "آیا موقعیت و مخاطب و پرسشِ پیشینِ سخن معلوم است؟", conf: "خواندن سخن بیرون از موقعیتش.", ex: "قرینهٔ کلام معصوم در حدیث «خلق‌الله آدم علی صورته».", st: ["st_r_disagree"] },
  { id: "c_r_taqiyya", fa: "تقیه", en: "Precautionary dissimulation (taqiyya)", def: "بیان برخی تعابیر برای حفظ جان اصحاب؛ جزوه آن را در شمار قرائنی می‌آورد که توجه یا غفلت از آن‌ها سبب اختلاف در فهم احادیث است.", secs: ["s85"], vs: ["c_r_shan"], crit: "آیا شرایط صدور (خطر برای جان اصحاب) شاهدی بر تقیه‌ای بودن تعبیر دارد؟", conf: "یا تعبیر تقیه‌ای را حکم واقعی گرفتن، یا بی‌شاهد هر تعبیر ناخوشایندی را تقیه دانستن.", ex: "— (جزوه مصداق مشخص نیاورده است)", st: ["st_r_disagree"] },
  { id: "c_r_kab", fa: "کعب (مثال اختلاف معنای واژه)", en: "Kaʿb", def: "واژهٔ آیهٔ وضو که اختلاف در معنای آن (برآمدگی روی پا، مفصل ساق و قدم، یا قوزک پا) مثال جزوه برای عامل سوم اختلاف است. پانوشت: «۱. استخوان برآمده پشت پا. ۲. استخوان موجود بین مفصل ساق پا و قدم پا که استخوان ساق بر روی آن قرار می‌گیرد. ۳. استخوان (قوزک) برآمده در دو طرف مفصل پا.»", secs: ["s85"], vs: ["c_r_dalalat"], crit: "آیا واژهٔ کلیدی بیش از یک معنای لغوی یا اصطلاحی محتمل دارد و هر معنا حکم متفاوتی می‌دهد؟", conf: "پنداشتن این‌که واژه یک معنای بدیهی دارد.", ex: "حد مسح پا در وضو.", st: ["st_r_disagree"] },
  { id: "c_r_pluralism", fa: "پلورالیسم (کثرت‌گرایی)", en: "Pluralism", def: "پذیرش کثرت در برابر وحدت؛ در سیاست (تعدد احزاب) و فرهنگ (پذیرش خرده‌فرهنگ‌ها) مطرح است و در دین، فراتر از تعدد قرائت‌های درون‌دینی، حقانیت و اعتبار همهٔ ادیان و کیش‌ها، اعم از توحیدی، غیرتوحیدی و حتی ساخته‌های بشری را یکسان فرض می‌کند.", secs: ["s81"], vs: ["c_r_taddod", "c_r_enhesar", "c_r_shomul"], crit: "آیا ادعا دربارهٔ ادیان مختلف است (نه برداشت‌های درون یک دین)؟ و در کدام ساحت؟", conf: "یکی گرفتن پلورالیسم دینی با تعدد قرائت‌ها یا با مدارای اجتماعی.", ex: "نظریهٔ جان هیک.", st: ["st_r_plural"] },
  { id: "c_r_pl_epi", fa: "پلورالیسم معرفت‌شناختی (حقانیت)", en: "Epistemic/alethic pluralism", def: "ادعای حقانیت و صدق یکسان باورهای متعارض ادیان؛ با برهان عقلی مردود است زیرا حقانیت برهانی منحصر در یک حقیقت و اجتماع نقیضین ناممکن است.", secs: ["s81", "s83"], vs: ["c_r_pl_najat", "c_r_pl_raftar"], crit: "آیا ادعا دربارهٔ صدق و انطباق با واقع است؟", conf: "مدارا یا امید به نجات دیگران را مستلزم آن دانستن.", ex: "«توحید و تثلیث هر دو به یک اندازه درست‌اند.»", st: ["st_r_plural"] },
  { id: "c_r_pl_najat", fa: "پلورالیسم نجات (رستگاری)", en: "Soteriological pluralism", def: "فرض بهشتی شدن پیروان همهٔ ادیان صرف‌نظر از حقانیت عقایدشان. در نگرش اسلامی جزوه، نجات شامل پیروان دین حق فعلی، پیروان ادیان گذشته در زمان اعتبار شریعتشان و جاهلان قاصر می‌شود و فقط معاندان و مقصران محروم‌اند.", secs: ["s81", "s86"], vs: ["c_r_pl_epi", "c_r_pl_raftar"], crit: "آیا ادعا دربارهٔ سرانجام اخروی است؟", conf: "انحصار حقانیت را مستلزم نفی نجات همهٔ غیرپیروان دانستن.", ex: "نجات قاصران.", st: ["st_r_plural"] },
  { id: "c_r_pl_raftar", fa: "پلورالیسم رفتاری (اخلاقی)", en: "Behavioural pluralism", def: "زیست مسالمت‌آمیز، دادگری و صلح با پیروان سایر آیین‌ها؛ اسلام آن را بر پایهٔ پیمان، عدالت و انصاف با غیرمسلمانان غیرمتخاصم به رسمیت می‌شناسد و حرمت جان، مال و حقوق اجتماعی اهل ذمه را حتی با بهره‌مندی از بیت‌المال تضمین می‌کند (ممتحنه ۸).", secs: ["s81", "s86"], vs: ["c_r_pl_epi", "c_r_pl_najat"], crit: "آیا ادعا دربارهٔ شیوهٔ زیستن و رفتار با دیگران است؟", conf: "پنداشتن این‌که مدارا مستلزم برابری صدق ادیان است، یا انحصار حقانیت مستلزم نزاع.", ex: "ممتحنه ۸: «لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين».", st: ["st_r_plural"] },
  { id: "c_r_talazom", fa: "مغالطهٔ تلازم", en: "Fallacy of false entailment", def: "فرض نادرست این‌که نفی پلورالیسم در مقام حقانیت (انحصار حقانیت در یک دین منطبق بر واقع) مستلزم محرومیت قاصران از نجات یا نفی همزیستی مسالمت‌آمیز و رفتار اخلاقی با پیروان دیگر ادیان است؛ ریشهٔ آن خلط سه ساحت است.", secs: ["s83", "s81", "s87"], vs: [], crit: "آیا نتیجه در ساحتی غیر از ساحت مقدمه است (حقانیت ← نجات یا رفتار)؟", conf: "تنها جهت «حقانیت ← نفی نجات/مدارا» را مغالطه دیدن و جهت وارونه «مدارا ← برابری حقانیت» را نادیده گرفتن (جهت وارونه، صورت‌بندی سامانه).", ex: "«اگر اسلام حق است، پس باید با پیروان دیگر ادیان جنگید.»", st: ["st_r_plural"] },
  { id: "c_r_enhesar", fa: "انحصارگرایی (در الهیات مسیحی)", en: "Exclusivism", def: "در گزارش جزوه از الهیات سنتی مسیحی: نجات صرفاً از طریق فداکاری عیسی مسیح و غسل تعمید ممکن دانسته می‌شد که نتیجه‌اش محرومیت گذشتگان و کودکان از نجات و فرض جایگاهی چون لیمبو بود. (در نمودار فصل: «از انحصارگرایی و شمول‌گرایی تا نسبی‌انگاری».)", secs: ["s82"], vs: ["c_r_shomul", "c_r_pluralism"], crit: "آیا نجات منحصر در پیروان صریح یک آیین دانسته می‌شود؟", conf: "یکی گرفتن «انحصار حقانیت» (موضع جزوه) با «انحصار نجات» (موضع الهیات سنتی مسیحی در گزارش جزوه).", ex: "لیمبو.", st: ["st_r_plural"] },
  { id: "c_r_shomul", fa: "شمول‌گرایی", en: "Inclusivism", def: "نظریهٔ کارل رانر که با اصطلاح «مسیحیان بی‌نام» دایرهٔ نجات را به افراد پایبند به اخلاق مسیحی تعمیم داد (به گزارش جزوه).", secs: ["s82"], vs: ["c_r_enhesar", "c_r_pluralism"], crit: "حقانیت یک دین حفظ می‌شود ولی نجات به کسانی بیرون از پیروان صریح آن نیز تعمیم می‌یابد.", conf: "یکی گرفتن شمول‌گرایی با پلورالیسم معرفت‌شناختی.", ex: "مسیحیان بی‌نام.", st: ["st_r_plural"] },
  { id: "c_r_anon", fa: "مسیحیان بی‌نام", en: "Anonymous Christians", def: "اصطلاح کارل رانر برای کسانی که بیرون از کلیسا نجات می‌یابند؛ به گزارش جزوه افراد پایبند به اخلاق مسیحی.", secs: ["s82"], vs: ["c_r_shomul"], crit: "نجات کسی که بیرون از پیروان صریح یک آیین است، به واسطهٔ همان آیین تبیین می‌شود.", conf: "یکی گرفتن آن با پلورالیسم: رانر حقانیت مسیحیت را حفظ می‌کند و فقط دایرهٔ نجات را می‌گشاید (برای صورت‌بندی دقیق خود رانر لایهٔ رقیب ایستگاه st_r_plural را ببین).", ex: "مرحلهٔ دوم سیر غربی در s82.", st: ["st_r_plural"] },
  { id: "c_r_gonah", fa: "گناه ذاتی (گناه نخستین)", en: "Original sin", def: "فرض الهیات سنتی مسیحی که بنابر آن نجات صرفاً از طریق فداکاری مسیح و غسل تعمید ممکن است؛ نجات در نگرش اسلامی برخلاف آن بر فطرت پاک انسانی و حقیقت‌جویی استوار است.", secs: ["s82", "s86"], vs: [], crit: "آیا نجات بر جبران گناهی موروثی بنا شده است؟", conf: "سنجیدن نگرش اسلامی به نجات با این چارچوب.", ex: "نمودار s87: «باور به گناه ذاتی و رستگاری انحصاری از طریق تعمید».", st: ["st_r_plural"] },
  { id: "c_r_limbo", fa: "لیمبو", en: "Limbo", def: "جایگاهی که الهیات سنتی مسیحی، در نتیجهٔ انحصار نجات در تعمید، برای گذشتگان و کودکان محروم از نجات فرض کرد.", secs: ["s82"], vs: ["c_r_enhesar"], crit: "نشانهٔ پیامد انحصار نجات: جایگاهی برای کسانی که بی‌تقصیر از شرط نجات (تعمید) محروم مانده‌اند.", conf: "خلط آن با شمول نجات قاصران در نگرش اسلامی جزوه.", ex: "گذشتگان پیش از مسیح و کودکان تعمیدنیافته (به گزارش s82).", st: ["st_r_plural"] },
  { id: "c_r_gohar_sadaf", fa: "گوهر و صدف دین (هیک)", en: "Kernel and shell", def: "تقسیم دین در نظریهٔ جان هیک به «گوهر» (تحول وجودی از خودمحوری به حق‌محوری) و «صدف» (گزاره‌های کلامی مانند توحید و تثلیث، شرایع و مناسک).", secs: ["s82", "s83"], vs: ["c_r_namadin"], crit: "آیا گزاره‌های کلامی، شرایع و مناسک «پوسته» و فقط تحول وجودی «گوهر» دانسته می‌شود؟", conf: "پنداشتن این‌که تعریف گوهر با فرض دست‌نیافتنی بودن حقیقت سازگار است (نقد تناقض درونی، s83).", ex: "توحید و تثلیث هر دو «صدف»اند.", st: ["st_r_plural"] },
  { id: "c_r_fil", fa: "تمثیل فیل در تاریکی", en: "Elephant parable", def: "تمثیلی که هیک (همراه با انگیزهٔ پایان دادن به تنش‌های مذهبی) به آن تکیه کرد تا ادعا کند برداشت همهٔ ادیان از حقیقت متعالی ناقص و در عین حال به یک اندازه معتبر است.", secs: ["s82"], vs: ["c_r_gohar_sadaf"], crit: "تمثیلی که برابری اعتبار برداشت‌های ناقص را از راه تشبیه ادیان به لمس‌کنندگان بخش‌های گوناگون یک فیل نتیجه می‌گیرد.", conf: "پنداشتن این‌که تمثیل بدون دسترسی راوی به کل حقیقت معنا دارد (صورت‌بندی سامانه از نقد s83).", ex: "تمثیل فیل در تاریکی در s82.", st: ["st_r_plural"] },
  { id: "c_r_hadi", fa: "اسم هادی و صفت مضل", en: "al-Hādī and al-Muḍill", def: "هدایت الهی از طریق ارائهٔ طریق (عقل و وحی) است نه ایصال اجباری به مقصد؛ از این رو اسم هادی با گمراهی اختیاری انسان‌ها منافات ندارد. صفت مضل به معنای فراهم شدن زمینهٔ گمراهی برای جویندگان باطل در چارچوب اراده و اختیار خود آنان است.", secs: ["s87"], vs: [], crit: "آیا استدلال از «هادی بودن خدا» به «رسیدن همه به مقصد» جهش می‌کند؟", conf: "هدایت را ایصال اجباری پنداشتن.", ex: "«خدا هادی است، پس همه هدایت‌شده‌اند.»", st: ["st_r_plural"] },
  { id: "c_r_islam_am", fa: "اسلام عام و اسلام خاص", en: "Islam in general vs specific sense", def: "اسلام در معنای عام تسلیم در برابر فرمان خدا در هر عصر است که با ظهور دین خاتم در شریعت اسلام خاص تعین یافته است.", secs: ["s87"], vs: ["c_r_naskh"], crit: "آیا سخن از تسلیم در هر عصر است یا از شریعت خاتم؟", conf: "استفاده از معنای عام برای اثبات اعتبار کنونی شرایع منسوخ.", ex: "پاسخ به استناد به بقره ۶۲.", st: ["st_r_plural"] },
  { id: "c_r_naskh", fa: "نسخ شرایع", en: "Abrogation", def: "پایان اعتبار یک شریعت پیشین با آمدن شریعت بعد؛ آیهٔ ۶۲ بقره ناظر به پیروان شرایع پیشین در زمان رواج همان ادیان و پیش از نسخ آن‌هاست.", secs: ["s87", "s86"], vs: ["c_r_islam_am"], crit: "آیا سخن دربارهٔ زمان اعتبار شریعت است یا پس از نسخ؟", conf: "تعمیم حکم زمان اعتبار به پس از نسخ.", ex: "صابئین، یهود و نصاری در زمان رواج ادیانشان.", st: ["st_r_plural"] },
  { id: "c_r_ahl_fatrat", fa: "اهل فترت", en: "People of the interval", def: "در نمودار فصل ۱۵: نجات اهل فترت و جاهلان قاصر، و رستگاری بر پایهٔ فطرت و حقیقت‌جویی. (توضیح سامانه: کسانی که در فاصلهٔ میان پیامبران زیسته و پیامی به آنان نرسیده است.)", secs: ["s86"], vs: ["c_r_qasir"], crit: "آیا پیام دین حق به آنان نرسیده و راهی به آن نداشته‌اند؟", conf: "محروم دانستن آنان از نجات به صرف پیرو نبودن.", ex: "نمودار تقابل پایانی فصل ۱۵.", st: ["st_r_plural"] },
  { id: "c_r_ahl_zimma", fa: "اهل ذمه", en: "Protected non-Muslims (dhimmī)", def: "غیرمسلمانانی که حرمت جان، مال و حقوق اجتماعی‌شان بر پایهٔ پیمان تضمین شده است، حتی با بهره‌مندی از بیت‌المال (s86).", secs: ["s86"], vs: ["c_r_pl_raftar"], crit: "آیا رابطه بر پایهٔ پیمان و با غیرمسلمانان غیرمتخاصم است؟", conf: "پنداشتن این‌که انحصار حقانیت با تضمین حقوق غیرمسلمانان ناسازگار است.", ex: "تضمین حقوق اهل ذمه حتی با بهره‌مندی از بیت‌المال (s86).", st: ["st_r_plural"] },
  { id: "c_r_toroq", fa: "«الطرق الی الله بعدد نفوس الخلائق»", en: "The ways to God are as many as the souls of creatures", def: "عبارتی که مدعیان پلورالیسم به آن استناد کرده‌اند؛ طبق جزوه فاقد هرگونه سند روایی است و بر زبان برخی عرفا جاری شده و مراد اهل معرفت از آن تکثر شیوه‌ها و آیات خداشناسی (براهین عقلی، نظم جهان، شهود فطری و مراتب گوناگون علم حضوری) برای رهنمون شدن به حقیقت واحد است، نه حقانیت شرایع گوناگون و منسوخ.", secs: ["s87"], vs: ["c_r_hadi"], crit: "آیا سند روایی دارد؟ مراد گوینده تکثر «راه شناخت» است یا تکثر «شریعت معتبر»؟", conf: "حدیث پنداشتن آن و خواندن آن به‌عنوان اعتبار همهٔ شرایع.", ex: "استناد مدعیان پلورالیسم به آن (s87).", st: ["st_r_plural", "st_r_sources"] }
);

