    "نمودار «سلسله‌مراتب ابزارها و قواعد معرفت‌شناسی دینی»: مرتبهٔ اول، معارف پایه و یقینی: شهود و علم حضوری (پایهٔ خطاناپذیر و درک فطری نسبت به حقایق بنیادین) و براهین عقلی قطعی (اثبات انحصاری اصول اعتقادی نظیر توحید و نبوت). مرتبهٔ دوم، معارف تفصیلی شریعت: نصوص و ادلهٔ نقلی (مرجع فهم جزئیات شریعت با ارزیابی سند و دلالت) و رجوع به متخصص اعلم (تکلیف عقلایی در پیروی از کارشناس در فروع دین). مرتبهٔ سوم، ضوابط داوری و رفع تعارض: قاعدهٔ تقدم یقین بر ظن (حل تعارض‌های بدوی میان ادله و کشف تکلیف واقعی).",
